import java.util.Scanner;

public class Main {
    static long digitCount(long number) {
        number = (number < 0) ? -number : number;
        long count = 0;
        while (number != 0) {
            ++count;
            number /= 10;
        }
        return count;
    }

    static long createOnes(long length) {
        long result = 0;
        for (int i = 0; i < length; ++i)
            result = result * 10 + 1;
        return result;
    }

    static long computeAux2(long number) {
        if (number == 0) return 0;
        number = (number < 0) ? -number : number;
        long d = digitCount(number);
        return d + computeAux2(number - createOnes(d));
    }

    static long computeAux(long n, long s, long a, long m, int[] arr) {
        if (a >= m) return m;
        if (n == 0) return a;
        if (n < 0) { n = -n; s = -s; }
        long d = digitCount(n);
        long o_d = createOnes(d);
        long res1 = m, res2 = m;

        if (0 <= arr[(int)d] * s && -10 < arr[(int)d] && arr[(int)d] < 10) {
            arr[(int)d] += s;
            res1 = computeAux(n - o_d, s, a + d, m, arr);
            arr[(int)d] -= s;
        }
        if (0 <= arr[(int)(d + 1)] * s && -10 < arr[(int)(d + 1)] && arr[(int)(d + 1)] < 10) {
            arr[(int)(d + 1)] += s;
            res2 = computeAux(n - 10 * o_d - 1, s, a + d + 1, res1, arr);
            arr[(int)(d + 1)] -= s;
        }
        return res1 < res2 ? res1 : res2;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        int[] state = new int[20];
        System.out.println(computeAux(n, 1, 0, computeAux2(n), state));
        scanner.close();
    }
}

